#!/usr/bin/env python3
"""Append the two user-cited nickelate studies and four superconducting-percolation papers."""
from __future__ import annotations
import csv
from pathlib import Path

ROOT = Path(__file__).resolve().parent
sources = [
{
'id':'13','area':'Nickelate cation stoichiometry','citation':'Yueying Li, Wenjie Sun, Jiangfeng Yang, Xiangbin Cai, Wei Guo, Zhengbin Gu, Ye Zhu, and Yuefeng Nie, “Impact of Cation Stoichiometry on the Crystalline Structure and Superconductivity in Nickelates,” Frontiers in Physics 9, article 719534 (2021).','doi_or_identifier':'10.3389/fphy.2021.719534; arXiv:2106.02485','primary_url':'https://doi.org/10.3389/fphy.2021.719534','research_question':'How nominal cation stoichiometry in MBE-grown NdNiO3 and Nd0.8Sr0.2NiO3 precursor films affects structure, reduction, and superconducting transport, and whether out-of-plane lattice parameter can guide flux calibration.','methods_and_model':'Full open-access publisher article read. NdNiO3 and Nd0.8Sr0.2NiO3 films were grown by MBE on TiO2-terminated SrTiO3 while varying nominal Nd:Ni flux. RHEED, QCM, XRD/RSM, AFM, STEM/ADF, and four-probe transport were used. Reduction used CaH2 at 280 C for 4 h.','main_findings':'Off-optimal nominal Nd:Ni ratios associate with expanded out-of-plane lattice parameter; the authors fit this relation to guide MBE flux adjustment. Nominally 10% off-stoichiometric films show broader/weaker precursor peaks and some reduced-phase peaks; at 15% deviation few obvious infinite-layer peaks are observed. Off-stoichiometric reduced samples are insulating; the optimized sample has onset about 14.7 K and zero resistance about 4.7 K. RHEED impurity features are unresolved.','limitations':'The composition is a nominal beam-flux ratio, not direct absolute cation assay. Anion concentration also affects the lattice parameter. Diffraction and transport do not establish a general chemical endpoint. The study does not validate a cross-facility/batch predictor and reports no magnetic measurement.','relationship_to_projects':'Supports a narrow precursor-composition/structure relation and process-specific calibration. It does not establish an independent-batch predictor, definitive reduction endpoint, or magnetic response.','full_text_status':'Full open-access publisher HTML read; arXiv record checked; PDF not separately read.','evidence_stance':'Exact journal citation verified; support is narrow and process-specific.'
},
{
'id':'14','area':'Nickelate topochemical reduction','citation':'A. Gutiérrez-Llorente, A. Raji, D. Zhang, L. Divay, A. Gloter, F. Gallego, C. Galindo, M. Bibes, and L. Iglesias, “Toward Reliable Synthesis of Superconducting Infinite Layer Nickelate Thin Films by Topochemical Reduction,” Advanced Science 11(24), article 2309092 (2024).','doi_or_identifier':'10.1002/advs.202309092; arXiv:2401.12307','primary_url':'https://doi.org/10.1002/advs.202309092','research_question':'How precursor film quality and progressive CaH2 topochemical reduction affect superconducting transport in Pr0.8Sr0.2NiO2 thin films, including whether transport can track reduction progress.','methods_and_model':'Full article read via PMC and arXiv v2. 10–13-unit-cell Pr0.8Sr0.2NiO3 films were grown by PLD on STO; XPS assessed cation stoichiometry. A 5×5 mm film was cut into pieces; one piece was repeatedly reduced in evacuated sealed ampoules at 260 C for successive 150, 30, 25, and 45 min steps. XRD/RSM, four-probe transport, STEM/4D-STEM were used.','main_findings':'A resistive transition appeared after initial reduction; zero resistance followed further reduction. The final series reached onset near 9 K and Tc about 7.6 K. Structural data support the infinite-layer phase and apical-oxygen removal. Over-reduction can lower onset and deteriorate films.','limitations':'The central reduction trajectory is repeated treatment of the same specimen/piece, not independent batch replication; no success-rate or yield analysis. The system is ultrathin Pr0.8Sr0.2 on STO and one sealed-ampoule protocol. The accessible paper does not report magnetic screening; the supplementary PDF was not inspected.','relationship_to_projects':'Supports treatment progression and transport sensitivity for this specific Pr platform, but not independent-batch reproducibility or a general endpoint criterion. It does not validate spatial percolation or a nickelate interface Hamiltonian.','full_text_status':'Publisher metadata plus full PMC and arXiv v2 article text read; supplement PDF could not be retrieved.','evidence_stance':'Exact published citation verified. The preprint title uses “Towards”; published title uses “Toward.”'
},
{
'id':'15','area':'Superconducting precursor percolation','citation':'Damjan Pelc, Marija Vučković, Mihael S. Grbić, Miroslav Požek, Guichuan Yu, Takao Sasagawa, Martin Greven, and Neven Barišić, “Emergence of superconductivity in the cuprates via a universal percolation process,” Nature Communications 9, 4327 (2018).','doi_or_identifier':'10.1038/s41467-018-06707-y','primary_url':'https://doi.org/10.1038/s41467-018-06707-y','research_question':'Can superconducting precursor signals above Tc in several cuprates be explained by spatially inhomogeneous superconducting patches whose macroscopic response emerges by percolation?','methods_and_model':'Experimental nonlinear conductivity in multiple cuprate families plus a minimal nearest-neighbour site-percolation model of square/cubic patches. Local superconducting fraction P(T) is related to temperature; the simple model uses Pπ−P=(T−Tπ)/Ξ0 and explores a distribution of local gaps. Patches are static; Josephson couplings and proximity effects are neglected.','main_findings':'The measured nonlinear conductivity decays with temperature and field on a scale Ξ0. A minimal inhomogeneous-percolation model captures the reported dependencies better than the tested standard GL treatment. The paper reports site thresholds near 0.6 for 2D and 0.3 for 3D in its chosen lattice models.','limitations':'The model assumes static, perfectly connected patches and omits Josephson/proximity effects; the authors note these assumptions are poor in regimes near Tc or well above it. The reported evidence is for cuprates, not nickelates, and does not validate a reduction-proxy window or correlated random field for nickelate films.','relationship_to_projects':'Directly shows that the general idea “local superconducting patches become globally superconducting by percolation” is established in cuprate literature. The nickelate manuscript must claim a narrower contribution: a material-calibrated proxy, covariance-controlled prediction, or batch-level validation—not generic percolative emergence.','full_text_status':'Full open-access PMC article read; supplementary information is listed and available, but not separately inspected in this targeted review.','evidence_stance':'Peer-reviewed experimental/model paper; relevant prior art, not direct nickelate evidence.'
},
{
'id':'16','area':'Thickness-dependent superconducting percolation context','citation':'Han-Byul Jang, Ji Soo Lim, and Chan-Ho Yang, “Film-thickness-driven superconductor to insulator transition in cuprate superconductors,” Scientific Reports 10, article 3236 (2020).','doi_or_identifier':'10.1038/s41598-020-60037-y','primary_url':'https://doi.org/10.1038/s41598-020-60037-y','research_question':'How film thickness affects the superconductor-insulator transition in optimally doped La1.85Sr0.15CuO4 epitaxial films.','methods_and_model':'Full open article read. PLD LSCO films on lattice-matched LaAlO3 ranged from 6 to about 300 nm. Four-probe transport, XRD/RSM, STEM, and XPS were used. The paper interprets thickness-dependent transport using disorder, oxygen vacancies, weak localization, and a percolation picture; it is not a direct spatially resolved percolation simulation.','main_findings':'Transport shows a thickness-driven transition near 10 nm. XPS suggests oxygen vacancies near the interface. The authors discuss local superconducting and metallic/insulating states and state that supercurrent paths must percolate; the effective dimensionality and percolation threshold may depend on film thickness and coherence length.','limitations':'The percolation mechanism is proposed rather than directly mapped or measured. Data availability is by reasonable request. LSCO results cannot be transferred quantitatively to nickelates.','relationship_to_projects':'Demonstrates prior discussion of thickness, disorder, oxygen vacancies, and percolation in superconducting oxide films. It narrows the novelty of generic “correlation changes connectivity” while reinforcing the need for spatially resolved validation.','full_text_status':'Full open Nature/Springer article read, including methods, discussion, conclusion, and data statement.','evidence_stance':'Peer-reviewed experimental evidence with a proposed, not directly verified, percolative interpretation.'
},
{
'id':'17','area':'Disordered-superconductor local pairing','citation':'K. H. Sarwa B. Tan, Kevin A. Parendo, and A. M. Goldman, “Evidence of spatially inhomogeneous pairing on the insulating side of a disorder-tuned superconductor-insulator transition,” Physical Review B 78, 014506 (2008).','doi_or_identifier':'10.1103/PhysRevB.78.014506; arXiv:0704.0765','primary_url':'https://doi.org/10.1103/PhysRevB.78.014506','research_question':'Whether insulating amorphous InxOy films near a disorder-tuned superconducting transition contain spatially inhomogeneous superconducting pairing even without granular morphology.','methods_and_model':'Transport, magnetic-field dependence, and nonlinear conductance-voltage measurements on amorphous InxOy films; films were annealed at low temperature to tune resistance. A network/percolation interpretation treats superconducting clusters as Josephson-coupled islands in an insulating matrix, with global zero-resistance behavior requiring a spanning supercluster.','main_findings':'The authors observe strong resistance upturns and nonlinear conductance consistent with local pairing islands on the insulating side. They argue that islands or superclusters do not form a film-spanning superconducting path in this regime.','limitations':'The evidence is indirect transport/tunneling-like behavior, not a spatial image of pairing domains. The percolation network is conceptual and does not establish nickelate oxygen-proxy thresholds. Publisher full text is gated; full arXiv manuscript was read.','relationship_to_projects':'Directly establishes prior physical discussion of local superconducting islands and percolating global paths in disordered films. It cautions against equating a geometric threshold map with a measured transport path without coupling and conductance physics.','full_text_status':'Full arXiv manuscript v2 read; APS publisher record and abstract checked; publisher article text required authorization.','evidence_stance':'Peer-reviewed paper with full accessible author manuscript; interpretation is based on transport evidence.'
},
{
'id':'18','area':'Transport measurement controls','citation':'I. Tamir et al., “Sensitivity of the superconducting state in thin films,” Science Advances 5(3), eaau3826 (2019).','doi_or_identifier':'10.1126/sciadv.aau3826','primary_url':'https://doi.org/10.1126/sciadv.aau3826','research_question':'Whether the low-temperature metallic-like transport observed in thin superconductors is intrinsic or can be induced by external measurement perturbations.','methods_and_model':'Full PMC article read. Compared amorphous indium-oxide and exfoliated 2H-NbSe2 films, used external low-pass filtering, varied measurement current, and measured resistance versus temperature and magnetic field.','main_findings':'Filtering electrical lines removed apparent low-temperature resistance saturation in the studied cases; higher measurement current could reintroduce saturation. The paper attributes these effects to sensitivity/heating, emphasizing careful filtering and low-current checks.','limitations':'The study does not model percolation and concerns different superconductors; it is a measurement-control precedent, not nickelate-specific evidence. Its conclusions should not be generalized beyond the tested samples without qualification.','relationship_to_projects':'Relevant to the proposed joint transport-plus-magnetic endpoint: it underscores that current, filtering, and thermalization controls matter before assigning connectivity or superconducting mechanisms from transport alone.','full_text_status':'Full open-access PMC article read.','evidence_stance':'Peer-reviewed experimental control study.'
}
]

csv_path = ROOT / 'literature_comparison.csv'
fields = ['id','citation','doi_or_identifier','primary_url','research_question','methods_and_model','main_findings','limitations','relationship_to_projects','full_text_status','evidence_stance']
with csv_path.open('a', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=fields)
    for s in sources:
        writer.writerow({k:s.get(k,'') for k in fields})

md = ['\n## Additional verified studies and manuscript citations\n']
for s in sources:
    md += [f"### [{s['id']}] {s['citation']}",
           f"**DOI/identifier:** {s['doi_or_identifier']}. **Research question:** {s['research_question']}",
           f"**Methods/model:** {s['methods_and_model']}",
           f"**Findings:** {s['main_findings']}",
           f"**Limitations and relevance:** {s['limitations']} {s['relationship_to_projects']}",
           f"**Access and evidence status:** {s['full_text_status']} {s['evidence_stance']}",
           f"**Primary record:** {s['primary_url']}", '']
md += ['## References', '']
references = {
'1':('https://doi.org/10.1038/s41586-019-1496-5','Superconductivity in an infinite-layer nickelate'),
'2':('https://doi.org/10.1021/acs.nanolett.0c01392','A superconducting praseodymium nickelate with infinite layer structure'),
'3':('https://doi.org/10.1126/sciadv.abl9927','Superconductivity in infinite-layer nickelate La1−xCaxNiO2 thin films'),
'4':('https://doi.org/10.1103/PhysRevX.10.011024','Similarities and differences between LaNiO2 and CaCuO2 and implications for superconductivity'),
'5':('https://doi.org/10.1103/PhysRevB.100.205138','Formation of a two-dimensional single-component correlated electron system in NdNiO2'),
'6':('https://doi.org/10.1103/PhysRevB.70.165109','Infinite-layer LaNiO2: Ni1+ is not Cu2+'),
'7':('https://doi.org/10.1038/nature02308','A high-mobility electron gas at the LaAlO3/SrTiO3 heterointerface'),
'8':('https://doi.org/10.1038/nature02450','Electronic reconstruction at an interface between a Mott insulator and a band insulator'),
'9':('https://doi.org/10.1103/PhysRevB.80.241103','Berry-phase theory of polar discontinuities at oxide-oxide interfaces'),
'10':('https://doi.org/10.1103/PhysRevB.27.413','Critical phenomena in systems with long-range-correlated quenched disorder'),
'11':('https://doi.org/10.1103/PhysRevE.88.052102','Percolation with long-range correlated disorder'),
'12':('https://doi.org/10.1103/PhysRevE.96.062125','Percolation thresholds and fractal dimensions for square and cubic lattices with long-range correlated defects'),
'13':('https://doi.org/10.3389/fphy.2021.719534','Impact of cation stoichiometry on the crystalline structure and superconductivity in nickelates'),
'14':('https://doi.org/10.1002/advs.202309092','Toward reliable synthesis of superconducting infinite layer nickelate thin films by topochemical reduction'),
'15':('https://doi.org/10.1038/s41467-018-06707-y','Emergence of superconductivity in the cuprates via a universal percolation process'),
'16':('https://doi.org/10.1038/s41598-020-60037-y','Film-thickness-driven superconductor to insulator transition in cuprate superconductors'),
'17':('https://doi.org/10.1103/PhysRevB.78.014506','Evidence of spatially inhomogeneous pairing on the insulating side of a disorder-tuned superconductor-insulator transition'),
'18':('https://doi.org/10.1126/sciadv.aau3826','Sensitivity of the superconducting state in thin films')}
for i,(url,title) in references.items():
    md.append(f'[{i}]: {url} "{title}"')
(ROOT / 'literature_review.md').open('a').write('\n'.join(md)+'\n')
(ROOT / 'additional_literature_sources.json').write_text(__import__('json').dumps(sources,indent=2,ensure_ascii=False)+'\n')
print(f'Appended {len(sources)} sources; literature table now has {18} studies.')
